/**
 * Pure recipe helpers. Editing always produces a new recipe from the previous one by
 * replacing exactly one zone; the other zones are carried over by reference so
 * "preserved" is verifiable (brief §8.4).
 */
import { ZONES, type LookRecipe, type Zone, type ZoneRecipe } from './types.js';

function zoneKey(z: ZoneRecipe): string {
  return z.enabled ? `${z.shadeId}:${z.finish}:${z.intensity}` : 'off';
}

/** Deterministic id from the render-relevant fields (cache key for the same selfie + recipe). */
export function recipeId(r: Pick<LookRecipe, Zone | 'variant'>): string {
  const raw = `${r.variant}|${ZONES.map((z) => zoneKey(r[z])).join('|')}`;
  let h = 5381;
  for (let i = 0; i < raw.length; i++) h = ((h << 5) + h + raw.charCodeAt(i)) | 0;
  return `r${(h >>> 0).toString(36)}`;
}

export function sameZone(a: ZoneRecipe, b: ZoneRecipe): boolean {
  return zoneKey(a) === zoneKey(b);
}

export function changedZones(before: LookRecipe, after: LookRecipe): Zone[] {
  return ZONES.filter((z) => !sameZone(before[z], after[z]));
}

export function preservedZones(before: LookRecipe, after: LookRecipe): Zone[] {
  return ZONES.filter((z) => sameZone(before[z], after[z]));
}

/** Replace one zone; text fields are regenerated by the translation service for the new recipe. */
export function withZone(recipe: LookRecipe, zone: Zone, next: ZoneRecipe): LookRecipe {
  const draft = { ...recipe, [zone]: next };
  return { ...draft, id: recipeId(draft) };
}

export function activeZones(recipe: LookRecipe): Zone[] {
  return ZONES.filter((z) => recipe[z].enabled);
}

/** Ordered palette for swatch rows: eyes, lips, cheeks (enabled only). */
export function recipePalette(recipe: LookRecipe): { zone: Zone; shadeId: string }[] {
  return activeZones(recipe).map((zone) => ({ zone, shadeId: recipe[zone].shadeId }));
}
